  `status` enum('Open','Under Review','Resolved','Rejected') COLLATE utf8mb4_unicode_ci DEFAULT 'Open',
  `resolution_type` enum('Full Refund','Partial Refund') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `opened_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `resolved_at` datetime DEFAULT NULL,
  PRIMARY KEY (`dispute_id`),
  KEY `FK_DISPUTES_ORDER` (`order_id`),
  KEY `FK_DISPUTES_BUYER` (`buyer_id`),
  KEY `FK_DISPUTES_SELLER` (`seller_id`),
  CONSTRAINT `FK_DISPUTES_BUYER` FOREIGN KEY (`buyer_id`) REFERENCES `BUYER` (`buyer_id`),
  CONSTRAINT `FK_DISPUTES_ORDER` FOREIGN KEY (`order_id`) REFERENCES `ORDERS` (`order_id`),
  CONSTRAINT `FK_DISPUTES_SELLER` FOREIGN KEY (`seller_id`) REFERENCES `SELLER` (`seller_id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
