--
-- Table structure for table `LISTINGS`
--

DROP TABLE IF EXISTS `LISTINGS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `LISTINGS` (
  `listing_id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `price` decimal(10,2) NOT NULL,
  `original_price` decimal(10,2) DEFAULT NULL,
  `base_currency` enum('PHP','USD','KRW') COLLATE utf8mb4_unicode_ci DEFAULT 'PHP',
  `condition_grade` enum('Brand New','Like New','Lightly Used','Well Used','Heavily Used') COLLATE utf8mb4_unicode_ci NOT NULL,
  `target_gender` enum('Men','Women','Unisex','Kids') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `made_in` enum('Argentina','Australia','Brazil','Canada','China','France','Germany','India','Indonesia','Italy','Japan','Malaysia','Mexico','New Zealand','Philippines','Singapore','South Africa','South Korea','Spain','Taiwan','Thailand','United Kingdom','United States','Vietnam','Other') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `category_id` int NOT NULL,
  `seller_id` int NOT NULL,
  `product_line_id` int NOT NULL,
  `size_id` int NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`listing_id`),
  KEY `FK_LISTINGS_CATEGORY` (`category_id`),
  KEY `FK_LISTINGS_SELLER` (`seller_id`),
  KEY `FK_LISTINGS_PROD_LINE` (`product_line_id`),
  KEY `FK_LISTINGS_SIZE` (`size_id`),
  CONSTRAINT `FK_LISTINGS_CATEGORY` FOREIGN KEY (`category_id`) REFERENCES `CATEGORIES` (`category_id`),
  CONSTRAINT `FK_LISTINGS_PROD_LINE` FOREIGN KEY (`product_line_id`) REFERENCES `PRODUCT_LINES` (`product_line_id`),
  CONSTRAINT `FK_LISTINGS_SELLER` FOREIGN KEY (`seller_id`) REFERENCES `SELLER` (`seller_id`),
  CONSTRAINT `FK_LISTINGS_SIZE` FOREIGN KEY (`size_id`) REFERENCES `CATEGORY_SIZES` (`size_id`)
) ENGINE=InnoDB AUTO_INCREMENT=320 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

