/*!50003 CREATE*/ /*!50017 DEFINER=`kyrstie`@`localhost`*/ /*!50003 TRIGGER `after_listing_price_change_update_pricing_score` AFTER UPDATE ON `LISTINGS` FOR EACH ROW BEGIN
    DECLARE v_min DECIMAL(10,2);
    DECLARE v_max DECIMAL(10,2);
    DECLARE v_score DECIMAL(5,2);

    IF NEW.price <> OLD.price THEN
        SELECT estimated_price_min, estimated_price_max
          INTO v_min, v_max
          FROM PRODUCT_LINES WHERE product_line_id = NEW.product_line_id;

        IF v_min IS NOT NULL AND v_max IS NOT NULL THEN
            IF NEW.price BETWEEN v_min AND v_max THEN
                SET v_score = 100;
            ELSEIF NEW.price > v_max THEN
                SET v_score = GREATEST(0, 100 - ((NEW.price - v_max) / v_max) * 100);
            ELSE
                SET v_score = GREATEST(50, 100 - ((v_min - NEW.price) / v_min) * 50);
            END IF;

            UPDATE LISTING_ANALYTICS
               SET pricing_score = v_score,
                   completeness_score = LEAST(100, (IFNULL(photo_score,60) + IFNULL(details_score,60) + IFNULL(condition_score,60) + IFNULL(shipping_score,60) + v_score) / 5)
             WHERE listing_id = NEW.listing_id;
        END IF;
    END IF;
END */;;
DELIMITER ;
