DROP TABLE IF EXISTS `LISTING_MATERIALS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `LISTING_MATERIALS` (
  `listing_id` int NOT NULL,
  `material_id` int NOT NULL,
  PRIMARY KEY (`listing_id`,`material_id`),
  KEY `material_id` (`material_id`),
  CONSTRAINT `LISTING_MATERIALS_ibfk_1` FOREIGN KEY (`listing_id`) REFERENCES `LISTINGS` (`listing_id`) ON DELETE CASCADE,
  CONSTRAINT `LISTING_MATERIALS_ibfk_2` FOREIGN KEY (`material_id`) REFERENCES `MATERIALS` (`material_id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
