--
-- Table structure for table `ORDERS`
--

DROP TABLE IF EXISTS `ORDERS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ORDERS` (
  `order_id` int NOT NULL AUTO_INCREMENT,
  `order_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `status` enum('Preparing','Shipped','Out for Delivery','Delivered','Cancelled') COLLATE utf8mb4_unicode_ci DEFAULT 'Preparing',
  `listing_id` int NOT NULL,
  `buyer_id` int NOT NULL,
  `seller_id` int NOT NULL,
  `shipping_street` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_city` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_province` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `shipping_zip` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`order_id`),
  KEY `FK_ORDERS_LISTING` (`listing_id`),
  KEY `FK_ORDERS_BUYER` (`buyer_id`),
  KEY `FK_ORDERS_SELLER` (`seller_id`),
  CONSTRAINT `FK_ORDERS_BUYER` FOREIGN KEY (`buyer_id`) REFERENCES `BUYER` (`buyer_id`),
  CONSTRAINT `FK_ORDERS_LISTING` FOREIGN KEY (`listing_id`) REFERENCES `LISTINGS` (`listing_id`),
  CONSTRAINT `FK_ORDERS_SELLER` FOREIGN KEY (`seller_id`) REFERENCES `SELLER` (`seller_id`)
) ENGINE=InnoDB AUTO_INCREMENT=234 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

