/*!50003 CREATE*/ /*!50017 DEFINER=`leila`@`localhost`*/ /*!50003 TRIGGER `after_order_status_change_notify_buyer` AFTER UPDATE ON `ORDERS` FOR EACH ROW BEGIN
    IF NEW.status <> OLD.status THEN
        INSERT INTO NOTIFICATIONS (buyer_id, title, message, notification_type)
        VALUES (
            NEW.buyer_id,
            CONCAT('Order Update: ', NEW.status),
            CONCAT('Order #', NEW.order_id, ' is now "', NEW.status, '".'),
            'ORDER'
        );
    END IF;
END */;;
DELIMITER ;
