/*!50003 CREATE*/ /*!50017 DEFINER=`leila`@`localhost`*/ /*!50003 TRIGGER `after_payment_update_create_transaction` AFTER UPDATE ON `PAYMENTS` FOR EACH ROW BEGIN
    IF NEW.payment_status = 'Completed' AND OLD.payment_status <> 'Completed' THEN
        INSERT INTO TRANSACTIONS (amount, order_id, payment_id)
        VALUES (NEW.amount_paid, NEW.order_id, NEW.payment_id);
    END IF;
END */;;
DELIMITER ;
