DROP TABLE IF EXISTS `PENALTIES`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PENALTIES` (
  `penalty_id` int NOT NULL AUTO_INCREMENT,
  `buyer_id` int DEFAULT NULL,
  `seller_id` int DEFAULT NULL,
  `reason` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `penalty_type` enum('Bidding Suspension','Selling Suspension','Wallet Freeze','Account Ban') COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('Active','Served','Expired') COLLATE utf8mb4_unicode_ci DEFAULT 'Active',
  `issued_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `period_end` datetime DEFAULT NULL,
  PRIMARY KEY (`penalty_id`),
  KEY `FK_PENALTIES_BUYER` (`buyer_id`),
  KEY `FK_PENALTIES_SELLER` (`seller_id`),
  CONSTRAINT `FK_PENALTIES_BUYER` FOREIGN KEY (`buyer_id`) REFERENCES `BUYER` (`buyer_id`),
  CONSTRAINT `FK_PENALTIES_SELLER` FOREIGN KEY (`seller_id`) REFERENCES `SELLER` (`seller_id`)
) ENGINE=InnoDB AUTO_INCREMENT=258 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

