DROP TABLE IF EXISTS `TRACKING_LOGS`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `TRACKING_LOGS` (
  `tracking_id` int NOT NULL AUTO_INCREMENT,
  `shipment_id` int NOT NULL,
  `location` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `status` enum('Preparing','Shipped','Out for Delivery','Delivered','Returned') COLLATE utf8mb4_unicode_ci NOT NULL,
  `remarks` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`tracking_id`),
  KEY `FK_TRACKING_LOGS_SHIPMENT` (`shipment_id`),
  CONSTRAINT `FK_TRACKING_LOGS_SHIPMENT` FOREIGN KEY (`shipment_id`) REFERENCES `SHIPMENTS` (`shipment_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=325 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

