CREATE DEFINER=`kyrstie`@`localhost` PROCEDURE `sp_checkout_listing`(
    IN p_listing_id INT, IN p_buyer_id INT, IN p_seller_id INT,
    IN p_base_amount DECIMAL(10,2), IN p_payment_method VARCHAR(10), IN p_gateway_ref VARCHAR(255),
    IN p_currency VARCHAR(3), IN p_amount_paid DECIMAL(10,2)
)
BEGIN
    DECLARE v_order_id INT;

    INSERT INTO ORDERS (listing_id, buyer_id, seller_id) VALUES (p_listing_id, p_buyer_id, p_seller_id);
    SET v_order_id = LAST_INSERT_ID();

    INSERT INTO PAYMENTS (payment_method, amount_paid, currency, payment_status, gateway_reference_token, order_id)
    VALUES (p_payment_method, p_amount_paid, p_currency, 'Completed', p_gateway_ref, v_order_id);

