CREATE DEFINER=`leila`@`localhost` PROCEDURE `sp_review_authentication`(IN p_listing_id INT, IN p_admin_id INT, IN p_status VARCHAR(20), IN p_remarks VARCHAR(255))
BEGIN
    DECLARE v_old_status VARCHAR(20);


    SELECT authentication_status INTO v_old_status
    FROM AUTHENTICATION WHERE listing_id = p_listing_id LIMIT 1;

    UPDATE AUTHENTICATION SET authentication_status = p_status, verified_by_admin_id = p_admin_id, remarks = p_remarks
    WHERE listing_id = p_listing_id;

    INSERT INTO AUDIT_LOGS (admin_id, action_taken, table_affected, record_id, old_value, new_value)
    VALUES (p_admin_id, CONCAT('Set authenticity status to ', p_status), 'AUTHENTICATION', p_listing_id, v_old_status, p_status);
END ;;
