CREATE DEFINER=`leila`@`localhost` PROCEDURE `sp_soft_delete_listing`(IN p_listing_id INT, IN p_seller_id INT)
BEGIN
    UPDATE LISTINGS SET deleted_at = NOW(), is_active = 0 WHERE listing_id = p_listing_id AND seller_id = p_seller_id;
END ;;
